{
  "references": [
    {
      "id": "R1",
      "summary_ko": "왼쪽 팔의 부자연스럽고 로봇 같으며 빠른 움직임"
    },
    {
      "id": "R2",
      "summary_ko": "아이스피크 물체의 길이가 변함"
    },
    {
      "id": "R3",
      "summary_ko": "얼음에 아이스피크를 내리칠 때 얼음이 튀는 물리적 현상이 부정확함"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "도구를 휘두르고 재배치할 때 등반가의 왼팔과 안전 끈이 아이스액스 손잡이와 비정상적으로 겹쳐짐/합쳐짐"
    },
    {
      "id": "C2",
      "summary_ko": "타격 시 사실적인 쪼개짐이나 침투 대신 아이스액스 날과 눈 표면이 모핑 변형을 보임"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 왼팔의 부자연스럽고 빠른 움직임에 대한 결함이고, C1은 왼팔 및 안전 끈이 손잡이와 겹치거나 융합되는 현상에 대한 것으로 결함 유형이 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 왼팔의 모션 이상을 다루는 반면, C2는 아이스액스와 눈 표면의 접촉 및 변형에 관한 것으로 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 아이스피크의 길이 변화에 대한 것이며, C1은 팔과 도구 간의 메시 겹침 현상을 설명하므로 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "C2에서 아이스액스 날의 모핑 변형이 R2의 길이 변화와 관련이 있을 수 있으나 설명된 현상이 완전히 동일한지 불확실합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3는 충격 시 튀는 얼음의 물리적 현상을 다루며, C1은 손과 손잡이의 병합 문제를 다루므로 서로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "두 설명 모두 얼음/눈을 찍을 때 발생하는 물리적 파편/침투 현상의 오류를 다루고 있으나, 파편 분산 오류와 표면 모핑 변형이라는 세부 결함 측면에서 완전히 같은 현상인지 불확실합니다."
    }
  ]
}
